class Solution {
public:
    int calculateMinimumHP(vector<vector<int>>& dungeon) {
        int m = (int)dungeon.size();
        int n = (int)dungeon[0].size();
        const int INF = 1'000'000'000;
        vector<int> dp(n + 1, INF);
        dp[n - 1] = 1; // post-princess requirement: end with >= 1 health
        for (int i = m - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                int below = dp[j];      // dp[i+1][j] (still from previous row)
                int right = dp[j + 1];  // dp[i][j+1] (already updated this row)
                int need = min(below, right) - dungeon[i][j];
                dp[j] = max(1, need);
            }
        }
        return dp[0];
    }
};
